def fmt(v):
    return ('%.8f' % v).rstrip('0').rstrip('.')


def circles(L):
    return [i for i in range(len(L) - 1) if L[i].strip() == '0' and L[i + 1] == 'CIRCLE']


def find(L, i, code):
    j = i
    while L[j] != code:
