def esc(s):
    s = unicodedata.normalize('NFC', s)
    return ''.join(ch if ord(ch) < 128 else '\\U+%04X' % ord(ch) for ch in s)


def wrap(s, n=40):
    out = []
    cur = ''
    for w in s.split(' '):
        if cur and len(cur) + 1 + len(w) > n:
            out.append(cur)
            cur = w
        else:
            cur = (cur + ' ' + w) if cur else w
    if cur:
        out.append(cur)
    return out


